import 'dart:convert'; import 'dart:io'; import 'package:csv/csv.dart'; import 'package:path_provider/path_provider.dart'; import 'package:share_plus/share_plus.dart'; import '../database/db_helper.dart';
class ExportService {
  Future<void> exportarPlantelCsv() async {final rows=await (await DbHelper.instance.db).query('aves',orderBy:'id'); final data=[['ID','Clube','Anilha','Ano','Sexo','Nome','Raça','Mutação','Categoria','Topete','Gaiola','Status'],...rows.map((r)=>[r['id'],r['clube_sigla'],r['anilha'],r['ano_nascimento'],r['sexo'],r['nome'],r['raca'],r['mutacao'],r['categoria_plumagem'],r['com_topete'],r['numero_gaiola'],r['status']])]; final dir=await getTemporaryDirectory();final f=File('${dir.path}/plantel.csv');await f.writeAsString(const ListToCsvConverter().convert(data));await Share.shareXFiles([XFile(f.path)],text:'Plantel - Canary Control Pro');}
  Future<void> exportarGenealogia(int aveId) async {final d=await DbHelper.instance.db; final r=await d.query('aves',where:'id=?',whereArgs:[aveId]); if(r.isEmpty)return; final root=r.first; final lines=<String>['Árvore genealógica','Ave: ${root['clube_sigla']}-${root['anilha']}']; Future<void> rec(dynamic id,int n,String rot) async {if(id==null)return;final x=await d.query('aves',where:'id=?',whereArgs:[id]);if(x.isEmpty)return;final a=x.first;lines.add('${'  '*n}$rot: ${a['clube_sigla']}-${a['anilha']} ${a['nome']??''}');await rec(a['pai_id'],n+1,'Pai');await rec(a['mae_id'],n+1,'Mãe');} await rec(root['pai_id'],1,'Pai');await rec(root['mae_id'],1,'Mãe');final dir=await getTemporaryDirectory();final f=File('${dir.path}/genealogia_${aveId}.txt');await f.writeAsString(lines.join('\n'));await Share.shareXFiles([XFile(f.path)],text:'Genealogia');}
  Future<void> relatorio() async {final s=await DbHelper.instance.resumo();final html='''<html><body><h1>Canary Control Pro</h1><h2>Relatório do Plantel</h2><p>Aves: ${s['aves']}</p><p>Ovos: ${s['ovos']}</p><p>Férteis: ${s['ferteis']}</p><p>Fertilidade: ${(s['fertilidade'] as num).toStringAsFixed(1)}%</p><p>Gerado em ${DateTime.now()}</p></body></html>''';final dir=await getTemporaryDirectory();final f=File('${dir.path}/relatorio.html');await f.writeAsString(html);await Share.shareXFiles([XFile(f.path)],text:'Relatório Canary Control Pro');}
}
